-- 22: PRE-FLIGHT for the six social website migrations 20261101100000 .. 20261105100000 (branch feat/social-backend). Read-only. It lists problems; ROWS = STOP.
-- GENERATED by supabase/go-live/build_social.py: do not edit it by hand.
--   * something these files create already exists (the files are plain CREATEs: they would fail), including the social-media bucket and its policies;
--   * something they rely on is missing (the earlier migrations, or an object that exists only in production).
-- A missing COLUMN of an existing table is not listed here: it stops that migration (nothing from it is applied) with a plain error, which is the same safe outcome.
-- On a database built from the repository's migrations before these six, it returns no rows.
select 'function already exists' as problem, p.proname::text as name
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
 where n.nspname = 'public' and p.proname = any(array['ai_caption_begin', 'block_list', 'block_set', 'cms_find_profiles', 'cms_list_banned_terms', 'cms_list_features', 'cms_profile_set_status', 'cms_publish_rules', 'cms_report_resolve', 'cms_reports_list', 'cms_set_banned_term', 'cms_set_feature', 'comment_add', 'comment_card', 'comment_delete', 'comment_list', 'dm_answer_request', 'dm_conversation', 'dm_conversation_json', 'dm_delete_message', 'dm_direct_closed', 'dm_group_add', 'dm_group_remove', 'dm_group_rename', 'dm_inbox', 'dm_is_member', 'dm_leave', 'dm_mark_read', 'dm_message_card', 'dm_messages', 'dm_mute', 'dm_new_member_status', 'dm_people', 'dm_ref_card', 'dm_require_inbox', 'dm_send', 'dm_start_booking', 'dm_start_direct', 'dm_start_group', 'dm_unread', 'explore_hot_events', 'explore_hot_venues', 'explore_professionals', 'feature_enabled', 'feed_home', 'feed_reels', 'feed_suggested', 'follow_list', 'follow_requests', 'follow_respond', 'follow_set', 'handle_available', 'handle_reserved', 'members_list', 'members_set', 'moderation_person_profiles', 'notification_prefs', 'notification_prefs_set', 'notifications_list', 'notifications_purge', 'notifications_read', 'notifications_unread', 'notify_on_comment', 'notify_on_follow', 'notify_on_like', 'notify_on_review_reply', 'notify_on_tag', 'notify_profile', 'post_card', 'post_create', 'post_delete', 'post_edit', 'post_get', 'post_like', 'post_save', 'post_untag', 'post_visible', 'profile_blocked_between', 'profile_can_act_as', 'profile_card', 'profile_clean_interests', 'profile_content_visible', 'profile_create_business', 'profile_get', 'profile_is_mine', 'profile_key', 'profile_mini', 'profile_my_ids', 'profile_my_profiles', 'profile_posts', 'profile_require_actor', 'profile_save_personal', 'profile_search', 'profile_update_business', 'profile_visible', 'report_create', 'review_can_reply', 'review_card', 'review_delete', 'review_eligibility', 'review_reply', 'review_reply_delete', 'review_save', 'review_summary', 'review_visited', 'reviews_list', 'rules_accept', 'rules_current', 'rules_status', 'save_venue_facts', 'saved_posts', 'site_features', 'site_handles_follow_profile', 'social_housekeeping', 'social_json_int', 'social_media_can_add', 'social_media_orphans', 'social_media_profile', 'social_media_visible', 'social_require_rules', 'social_rules_version', 'social_text_ok', 'stories_of', 'story_rail', 'story_seen', 'venue_ratings']::text[])
union all
select 'table already exists', t from unnest(array['site_feature_flags', 'site_profiles', 'site_handles', 'site_follows', 'site_blocks', 'site_posts', 'site_post_media', 'site_post_tags', 'site_post_likes', 'site_post_saves', 'site_comments', 'site_member_lists', 'site_story_views', 'site_banned_terms', 'site_community_rules', 'site_ai_caption_uses', 'site_rules_acceptance', 'site_reviews', 'site_review_replies', 'site_dm_conversations', 'site_dm_members', 'site_dm_messages', 'site_notifications', 'site_notification_opt_outs', 'site_reports']::text[]) t where to_regclass('public.' || t) is not null
union all
select 'column already exists', x from unnest(array['site_venues.amenities', 'site_venues.parking_info', 'site_venues.min_age', 'site_venues.id_required', 'site_venues.last_entry', 'site_venues.kitchen_hours', 'site_venues.menu_url']::text[]) x
  where exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = split_part(x, '.', 1) and c.column_name = split_part(x, '.', 2))
union all
select 'constraint already exists', x.c from (values ('site_venues', 'site_venues_amenities_known'), ('site_venues', 'site_venues_facts_lengths')) as x(t, c)
  where exists (select 1 from pg_constraint k where k.conname = x.c and k.conrelid = to_regclass('public.' || x.t))
union all
select 'index already exists', i.indexname::text from pg_indexes i where i.schemaname = 'public' and i.indexname = any(array['site_profiles_one_personal', 'site_profiles_one_per_venue', 'site_profiles_one_per_org_group', 'site_profiles_owner_idx', 'site_profiles_org_idx', 'site_profiles_handle_prefix', 'site_profiles_name_prefix', 'profiles_username_prefix_idx', 'profiles_name_prefix_idx', 'site_follows_followed_idx', 'site_follows_follower_idx', 'site_blocks_blocked_idx', 'site_blocks_keys_idx', 'site_blocks_blocked_key_idx', 'site_posts_author_idx', 'site_posts_feed_idx', 'site_posts_story_idx', 'site_post_media_poster_idx', 'site_post_tags_profile_idx', 'site_post_tags_event_idx', 'site_post_tags_venue_idx', 'site_post_tags_target_idx', 'site_post_likes_profile_idx', 'site_post_saves_profile_idx', 'site_comments_post_idx', 'site_comments_author_idx', 'site_comments_reply_idx', 'site_member_lists_member_idx', 'site_ai_caption_uses_user_idx', 'site_reviews_one_per_venue', 'site_reviews_one_per_event', 'site_reviews_venue_idx', 'site_reviews_event_idx', 'site_dm_one_direct', 'site_dm_one_per_booking', 'site_dm_members_profile_idx', 'site_dm_messages_conversation_idx', 'site_dm_messages_client_key_idx', 'site_notifications_recipient_idx', 'site_notifications_unread_idx', 'site_reports_one_per_reporter', 'site_reports_open_idx', 'site_reports_target_idx', 'site_reports_reporter_day_idx']::text[])
union all
select 'trigger already exists', t.tgname::text from pg_trigger t where not t.tgisinternal and t.tgname = any(array['site_handles_follow_profile', 'site_follows_notify', 'site_post_likes_notify', 'site_comments_notify', 'site_post_tags_notify', 'site_review_replies_notify']::text[])
union all
select 'storage policy already exists', p.policyname::text from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.policyname = any(array['social media readable by those who may see the post', 'profiles add their own social media', 'profiles remove their own social media']::text[])
union all
select 'storage bucket already exists', b.id::text from storage.buckets b where b.id = 'social-media'
union all
select 'MISSING prerequisite (a table, view or function the migrations use)', n from unnest(array['active_memberships', 'audit_log', 'can_access_venue', 'clean_social_links', 'is_cms_admin', 'is_org_member', 'profiles', 'site_events', 'site_orders', 'site_organizations', 'site_table_bookings', 'site_table_types', 'site_venues', 'site_verifications', 'venue_setup_log']::text[]) n
  where to_regclass('public.' || n) is null and not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = n)
union all
select 'MISSING prerequisite', 'storage schema (buckets, objects)' where to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null
union all
select 'MISSING prerequisite', 'auth.users' where to_regclass('auth.users') is null;
